const fs=require('fs');
const p='C:/Users/24380/AppData/Local/Programs/DeepSeek Harness/resources/app.asar';
const fd=fs.openSync(p,'r');
const head=Buffer.alloc(4200); fs.readSync(fd,head,0,4200,0);
const S=head.readUInt32LE(4);
const i=head.indexOf('{"files"');
if(i<0){console.log('marker not found, S=',S);process.exit(1);}
const jsonLen=S-(i-8);
const header=JSON.parse(head.slice(i,i+jsonLen).toString('utf8'));
const base=8+S;
const out=[];
(function walk(node,pre){for(const [k,v] of Object.entries(node.files||{})){const path=pre+'/'+k;if(v.files)walk(v,path);else out.push({path,size:v.size,offset:v.offset});}})(header,'');
console.log('jsonStart',i,'S',S,'jsonLen',jsonLen,'files',out.length,'base',base);
const pk=out.find(f=>f.path.endsWith('/package.json')&&f.path.split('/').length<=3);
console.log('probe:',pk.path,pk.size);
const b=Buffer.alloc(80); fs.readSync(fd,b,0,80,base+pk.offset); console.log(b.toString('utf8').slice(0,80));
const hits=out.filter(f=>/session/i.test(f.path)&&/\.(js|mjs|cjs)$/.test(f.path));
console.log('session js:',hits.length);
hits.slice(0,25).forEach(h=>console.log(' ',h.path,h.size));
fs.writeFileSync('C:/Users/24380/.dsh/asar-index.json',JSON.stringify({base,out}));
