const txt=buf.toString('utf8');
const start=txt.indexOf('{"files"');
let depth=0,end=-1,inStr=false,esc=false;
for(let i=start;i<txt.length;i++){const c=txt[i];
 if(inStr){ if(esc){esc=false;} else if(c==='\\'){esc=true;} else if(c==='"'){inStr=false;} continue;}
 if(c==='"'){inStr=true;continue;}
 if(c==='{')depth++; else if(c==='}'){depth--; if(depth===0){end=i+1;break;}}
}
const header=JSON.parse(txt.slice(start,end));
const base=8+S;
const out=[];
(function walk(n,pre){for(const [k,v] of Object.entries(n.files||{})){const q=pre+'/'+k;if(v.files)walk(v,q);else out.push({path:q,size:v.size,offset:Number(v.offset)});}})(header,'');
fs.writeFileSync(process.env.TEMP+'/asar-index.json',JSON.stringify({base,out}));
console.log('files',out.length,'S',S,'base',base);
const big=out.filter(f=>f.size>300000&&/\.(js|json|mjs|cjs)$/.test(f.path)).sort((a,b)=>b.size-a.size).slice(0,10);
big.forEach(f=>console.log(' ',f.path,f.size));
