 {dir:'--D-Work-DSH--',id:'session-b861a281-81f7-4deb-8ca0-eb1fcadffd41',cwd:'D:\\\\Work\\\\DSH'},
 {dir:'--D-Work-bodybuilding--',id:'session-5cbd28e2-1ec4-4239-b575-eb12877483cf',cwd:'D:\\\\Work\\\\bodybuilding'},
 {dir:'--D-Work-bodybuilding--',id:'session-5cb5d03d-9e5b-44f6-aff8-63514c834a9e',cwd:'D:\\\\Work\\\\bodybuilding'}
];
