  hdr.cwd=j.cwd;
  line0=JSON.stringify(hdr);
  const newFrame0=z.zstdCompressSync(Buffer.from(line0+'\n'));
  const parts=[newFrame0];
  for(let i=1;i<st.length;i++){const end=i+1<st.length?st[i+1]:buf.length;parts.push(buf.subarray(st[i],end));}
  const out=Buffer.concat(parts);
  const tmpPath=live+'.restore-tmp';
  fs.writeFileSync(tmpPath,out);
  if(fs.existsSync(live)) fs.copyFileSync(live, live+'.empty-before-restore');
  fs.renameSync(tmpPath, live);
  const chk=fs.readFileSync(live);
  const nf=frameStarts(chk).length;
  console.log(`${j.id.slice(8,16)} restored: ${before} -> ${hdr.cwd} | bytes ${buf.length} -> ${chk.length} | frames ${st.length} -> ${nf}`);
}
