{"command": "$code=@'
const fs=require('fs'),z=require('zlib'),path=require('path');
const MAGIC=Buffer.from([0x28,0xB5,0x2F,0xFD]);
const root='C:/Users/24380/.dsh/sessions';
const needle='财务分析';
function frames(b){const s=[];let i=0;while((i=b.indexOf(MAGIC,i))>=0){s.push(i);i+=4;}return s;}
for(const dir of fs.readdirSync(root)){
  const dp=path.join(root,dir);
  if(!fs.statSync(dp).isDirectory())continue;
  for(const sd of fs.readdirSync(dp)){
    const f=path.join(dp,sd,'session.v4.jsonl.zstd');
    if(!fs.existsSync(f))continue;
    const b=fs.readFileSync(f);const st=frames(b);
    let hits=[];
    for(let i=0;i<st.length;i++){
      try{
        const t=z.zstdDecompressSync(b.subarray(st[i], i+1<st.length?st[i+1]:b.length)).toString('utf8');
        let idx=0;
