const fs=require('fs'),z=require('zlib');
const MAGIC=Buffer.from([0x28,0xB5,0x2F,0xFD]);
const f='C:/Users/24380/.dsh/sessions/--C--Users-24380--dsh--im--/session-253e68d5-f8be-4645-bd8a-2228dcd41e8b/session.v4.jsonl.zstd';
const b=fs.readFileSync(f);const st=[];let i=0;while((i=b.indexOf(MAGIC,i))>=0){st.push(i);i+=4;}
let out=[];
for(let k=0;k<st.length;k++){
  const t=z.zstdDecompressSync(b.subarray(st[k], k+1<st.length?st[k+1]:b.length)).toString('utf8');
  for(const line of t.split('\n')){ if(!line.trim())continue;
    try{const o=JSON.parse(line); const d=o.data||{};
      if(o.type==='user/message'){const txt=(d.content||[]).map(c=>c.text||'').join(''); out.push({seq:o.seq,t:o.time,role:'user',txt:txt.slice(0,160)});}
      else if(o.type==='assistant/message'){const txt=(d.message&&d.message.content||[]).filter(c=>c.type==='text').map(c=>c.text).join(''); if(txt)out.push({seq:o.seq,t:o.time,role:'assistant',txt:txt.slice(0,200)});}
      else if(o.type==='session/title'){out.push({seq:o.seq,t:o.time,role:'TITLE',txt:d.title});}
    }catch(e){}
  }
}
console.log('total msgs', out.length);
for(const m of out.slice(-25)) console.log(new Date(m.t).toISOString().slice(5,19), '['+m.role+']', m.txt.replace(/\s+/g,' '));
