content.arguments:
{"content": "$ErrorActionPreference = 'Continue'
$log = 'D:\Work\_finalize2.log'
$dshExe = 'C:\Users\24380\AppData\Local\Programs\DeepSeek Harness\DeepSeek Harness.exe'
$py = 'C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\pythonw.exe'
function L([string]$m) { Add-Content -LiteralPath $log -Value ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $m) -Encoding UTF8 }
function Relaunch {
  try { Start-Process -FilePath $dshExe; L 'DSH relaunched' } catch { L "relaunch failed: $($_.Exception.Message)" }
  try {
    $shop = 'D:\Work\兵哥烧烤\meituan-agent'
    if ((Test-Path -LiteralPath (Join-Path $shop 'web_app.py')) -and (Test-Path -LiteralPath $py)) {
      Start-Process -FilePath $py -ArgumentList 'web_app.py','--port','8000' -WorkingDirectory $shop -WindowStyle Hidden
      L 'shop server restarted from D:\Work'
    } else { L 'shop server not restarted (missing file)' }
  } catch { L "shop restart failed: $($_.Exception.Message)" }
}
Set-Content -LiteralPath $log -Value '' -Encoding UTF8
L 'watcher started; waiting for DeepSeek Harness to exit'

$deadline = (Get-Date).AddMinutes(20)
$gone = $false
while ((Get-Date) -lt $deadline) {
  if (-not (Get-Process -Name 'DeepSeek Harness' -ErrorAction SilentlyContinue)) { $gone = $true; break }
  Start-Sleep -Seconds 2
}
if (-not $gone) { L 'TIMEOUT: DSH still running; no changes'; exit 1 }
Start-Sleep -Seconds 4
L 'DSH exited; starting work'

$src     = 'D:\BaiduSyncdisk\000\兵哥烧烤'
$dst     = 'D:\Work\兵哥烧烤'
$stale   = 'D:\Work\_stale-兵哥烧烤-20261123'
$sroot   = 'C:\Users\24380\.dsh\sessions'
$oldProj = Join-Path $sroot '--D-BaiduSyncdisk-000-~5175~54E5~70E7~70E4--'
$newProj = Join-Path $sroot '--D-Work-~5175~54E5~70E7~70E4--'
$defProj = Join-Path $sroot '--C-Users-24380-Documents-deepseek-harness-default-workspace--'
$regFile = 'C:\Users\24380\.dsh\storages\workspace.json'
$node    = (Get-Command node -ErrorAction SilentlyContinue).Source
if (-not $node) { $node = 'C:\Program Files\nodejs\node.exe' }

# 0. preflight
$left = @(Get-ChildItem -LiteralPath $src -Recurse -Force -File -ErrorAction SilentlyContinue)
$dfiles = @(Get-ChildItem -LiteralPath $dst -Recurse -Force -File -ErrorAction SilentlyContinue)
$dbytes = ($dfiles | Measure-Object -Property Length -Sum).Sum
L ("preflight: src_files=$($left.Count) dst_files=$($dfiles.Count) dst_bytes=$dbytes")
if ($left.Count -ne 0) { L 'ABORT: source still has files'; Relaunch; exit 1 }
if ($dfiles.Count -lt 9000) { L 'ABORT: destination looks incomplete'; Relaunch; exit 1 }

# 1. sessions project dir
if ((-not (Test-Path -LiteralPath $newProj)) -and (Test-Path -LiteralPath $oldProj)) {
  try { Rename-Item -LiteralPath $oldProj -NewName (Split-Path $newProj -Leaf) -ErrorAction Stop; L 'renamed project dir (D-BaiduSyncdisk-000 -> D-Work)' }
  catch { L "WARN: project dir rename failed: $($_.Exception.Message)" }
}
if (-not (Test-Path -LiteralPath $newProj)) { New-Item -ItemType Directory -Path $newProj | Out-Null; L 'created new project dir' }
if (Test-Path -LiteralPath $oldProj) {
  $n = 0
  foreach ($sd in (Get-ChildItem -LiteralPath $oldProj -Directory -ErrorAction SilentlyContinue)) {
    $t = Join-Path $newProj $sd.Name
    if (Test-Path -LiteralPath $t) { L "WARN: collision $($sd.Name)" }
    else { try { Move-Item -LiteralPath $sd.FullName -Destination $t -Force -ErrorAction Stop; $n++ } catch { L "WARN: move session dir failed: $($_.Exception.Message)" } }
  }
  L "moved $n session dir(s) out of old project dir"
  if (@(Get-ChildItem -LiteralPath $oldProj -Force -ErrorAction SilentlyContinue).Count -eq 0) { Remove-Item -LiteralPath $oldProj -Force -ErrorAction SilentlyContinue; L 'removed empty old project dir' }
}
if (Test-Path -LiteralPath $defProj) {
  $n = 0
  foreach ($sd in (Get-ChildItem -LiteralPath $defProj -Directory -ErrorAction SilentlyContinue)) {
    $t = Join-Path $newProj $sd.Name
    if (Test-Path -LiteralPath $t) { L "WARN: collision $($sd.Name)" }
    else { try { Move-Item -LiteralPath $sd.FullName -Destination $t -Force -ErrorAction Stop; $n++ } catch { L "WARN: move legacy session failed: $($_.Exception.Message)" } }
  }
  L "moved $n legacy session dir(s) from default-workspace project"
  if (@(Get-ChildItem -LiteralPath $defProj -Force -ErrorAction SilentlyContinue).Count -eq 0) { Remove-Item -LiteralPath $defProj -Force -ErrorAction SilentlyContinue; L 'removed empty legacy project dir' }
}

# 2. rewrite header cwd
& $node 'D:\Work\_fix_sessions_cwd.js' $newProj $dst 'pre-workmove-20261123' 2>&1 | ForEach-Object { L ("fixcwd: " + $_) }

# 3. registry
& $node 'D:\Work\_patch_workspace.js' $regFile $src $dst 2>&1 | ForEach-Object { L ("registry: " + $_) }

# 4. cleanup
$junction = 'C:\Users\24380\Documents\deepseek-harness\default-workspace'
if (Test-Path -LiteralPath $junction) {
  $ji = Get-Item -LiteralPath $junction -Force
  if ($ji.Attributes -band [IO.FileAttributes]::ReparsePoint) { Remove-Item -LiteralPath $junction -Force; L 'removed junction default-workspace' }
  else { L 'WARN: junction path is not a reparse point; left' }
}
$dh = 'C:\Users\24380\Documents\deepseek-harness'
if ((Test-Path -LiteralPath $dh) -and (@(Get-ChildItem -LiteralPath $dh -Force -ErrorAction SilentlyContinue).Count -eq 0)) { Remove-Item -LiteralPath $dh -Force; L 'removed empty deepseek-harness dir' }
if (Test-Path -LiteralPath $src) {
  $rest = @(Get-ChildItem -LiteralPath $src -Recurse -Force -ErrorAction SilentlyContinue)
  if ($rest.Count -eq 0) {
    try { Remove-Item -LiteralPath $src -Force -ErrorAction Stop; L 'removed old source dir' } catch { L "WARN: source dir removal failed: $($_.Exception.Message)" }
  } else { L "WARN: source not empty ($($rest.Count) entries); kept" }
}
if (Test-Path -LiteralPath $stale) { Remove-Item -LiteralPath $stale -Recurse -Force -ErrorAction SilentlyContinue; L 'deleted stale copy' }
foreach ($t in '_wmitest.ps1','_wmitest.txt','_wmicmd.txt','_psout.txt','_stop-dsh.cmd','_pstest.txt') {
  $p = Join-Path 'D:\Work' $t
  if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue }
}
L 'DONE'
Relaunch
", "file_path": "D:\Work\_finalize2.ps1"}

